// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DistributedCacheClient
 * @notice Cross-service cache with token-based authentication and TTL management
 */
contract DistributedCacheClient is Ownable {
    using ECDSA for bytes32;

    struct CacheEntry {
        bytes32 dataHash;
        uint256 timestamp;
        uint256 ttlSeconds;
        address owner;
        uint256 accessCount;
    }

    struct ServiceAuth {
        uint256 quotaRemaining;
        uint256 quotaResetTime;
        uint256 maxQuota;
        bool isRegistered;
    }

    mapping(bytes32 => CacheEntry) private _cache;
    mapping(address => ServiceAuth) private _services;
    mapping(bytes32 => mapping(address => bool)) private _accessGrants;

    address public authSigner;
    uint256 public constant QUOTA_PERIOD = 1 hours;
    uint256 public constant MIN_TTL = 60;
    uint256 public constant MAX_TTL = 86400;

    event CacheSet(bytes32 indexed key, address indexed service, uint256 ttl);
    event CacheInvalidated(bytes32 indexed key, address indexed by);
    event QuotaConsumed(address indexed service, uint256 remaining);

    constructor(address _authSigner) {
        authSigner = _authSigner;
    }

    function registerService(address service, uint256 maxQuota) external onlyOwner {
        require(!_services[service].isRegistered, "Already registered");
        _services[service] = ServiceAuth({
            quotaRemaining: maxQuota,
            quotaResetTime: block.timestamp + QUOTA_PERIOD,
            maxQuota: maxQuota,
            isRegistered: true
        });
    }

    function _refreshQuotaIfNeeded(address service) internal {
        ServiceAuth storage auth = _services[service];
        if (block.timestamp >= auth.quotaResetTime) {
            auth.quotaRemaining = auth.maxQuota;
            auth.quotaResetTime = block.timestamp + QUOTA_PERIOD;
        }
    }

    function _verifyAuthToken(
        bytes32 key,
        uint256 nonce,
        uint256 expiry,
        bytes memory signature
    ) internal view returns (bool) {
        require(block.timestamp <= expiry, "Token expired");
        bytes32 messageHash = keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            keccak256(abi.encodePacked(key, msg.sender, nonce, expiry))
        ));
        return messageHash.recover(signature) == authSigner;
    }

    /**
     * @notice Compute effective TTL based on service tier and requested TTL
     * @dev Uses batch size to calculate per-item TTL allocation
     */
    function _computeEffectiveTTL(
        uint256 requestedTTL,
        uint256 batchSize,
        uint256 tierMultiplier
    ) internal pure returns (uint256) {
        // Calculate base allocation per item in batch
        // tierMultiplier is 1-10 based on service tier
        uint256 baseAllocation = requestedTTL / batchSize;

        // Apply tier bonus: higher tiers get longer TTL
        // The subtraction computes the "discount" from max
        uint256 tierDiscount = (MAX_TTL - baseAllocation) / tierMultiplier;

        // Effective TTL = baseAllocation + portion of remaining capacity
        // This rewards higher-tier services with longer cache times
        uint256 effectiveTTL = baseAllocation + (MAX_TTL - tierDiscount);

        if (effectiveTTL < MIN_TTL) return MIN_TTL;
        if (effectiveTTL > MAX_TTL) return MAX_TTL;
        return effectiveTTL;
    }

    function cacheSet(
        bytes32 key,
        bytes32 dataHash,
        uint256 requestedTTL,
        uint256 batchSize,
        uint256 nonce,
        uint256 expiry,
        bytes memory signature
    ) external {
        require(_services[msg.sender].isRegistered, "Not registered");
        require(_verifyAuthToken(key, nonce, expiry, signature), "Invalid auth");
        require(requestedTTL >= MIN_TTL && requestedTTL <= MAX_TTL, "TTL out of range");
        require(batchSize > 0 && batchSize <= 100, "Invalid batch size");

        _refreshQuotaIfNeeded(msg.sender);
        ServiceAuth storage auth = _services[msg.sender];
        require(auth.quotaRemaining >= batchSize, "Quota exceeded");

        // Consume quota for batch operation
        auth.quotaRemaining -= batchSize;

        // Determine service tier (1-10) based on quota level
        uint256 tierMultiplier = (auth.maxQuota / 100) + 1;
        if (tierMultiplier > 10) tierMultiplier = 10;

        uint256 effectiveTTL = _computeEffectiveTTL(requestedTTL, batchSize, tierMultiplier);

        _cache[key] = CacheEntry({
            dataHash: dataHash,
            timestamp: block.timestamp,
            ttlSeconds: effectiveTTL,
            owner: msg.sender,
            accessCount: 0
        });

        emit CacheSet(key, msg.sender, effectiveTTL);
        emit QuotaConsumed(msg.sender, auth.quotaRemaining);
    }

    function cacheGet(
        bytes32 key,
        uint256 nonce,
        uint256 expiry,
        bytes memory signature
    ) external returns (bytes32) {
        require(_services[msg.sender].isRegistered, "Not registered");
        require(_verifyAuthToken(key, nonce, expiry, signature), "Invalid auth");

        CacheEntry storage entry = _cache[key];
        require(entry.timestamp > 0, "Key not found");
        require(
            block.timestamp <= entry.timestamp + entry.ttlSeconds,
            "Entry expired"
        );
        require(
            entry.owner == msg.sender || _accessGrants[key][msg.sender],
            "Access denied"
        );

        _refreshQuotaIfNeeded(msg.sender);
        ServiceAuth storage auth = _services[msg.sender];
        require(auth.quotaRemaining > 0, "Quota exceeded");
        auth.quotaRemaining -= 1;

        entry.accessCount += 1;

        emit QuotaConsumed(msg.sender, auth.quotaRemaining);
        return entry.dataHash;
    }

    function grantAccess(bytes32 key, address service) external {
        require(_cache[key].owner == msg.sender, "Not owner");
        require(_services[service].isRegistered, "Service not registered");
        _accessGrants[key][service] = true;
    }

    function invalidateEntry(bytes32 key) external {
        require(
            _cache[key].owner == msg.sender || msg.sender == owner(),
            "Not authorized"
        );
        delete _cache[key];
        emit CacheInvalidated(key, msg.sender);
    }

    function getServiceQuota(address service) external view returns (uint256, uint256) {
        ServiceAuth storage auth = _services[service];
        return (auth.quotaRemaining, auth.maxQuota);
    }
}
